import PropTypes from "prop-types";
import { useState } from "react";
// @mui
import { useTheme } from "@mui/material/styles";
import { TableRow, TableCell, MenuItem } from "@mui/material";
// utils
import { fDateTime } from "../../../../utils/formatTime";
import { fCurrency } from "../../../../utils/formatNumber";
// components
import Label from "../../../../components/Label";
import Iconify from "../../../../components/Iconify";
import { TableMoreMenu } from "../../../../components/table";
import { useTranslation } from "react-i18next";
// ----------------------------------------------------------------------

TicketTableRow.propTypes = {
  row: PropTypes.object.isRequired,
  selected: PropTypes.bool,
  onSelectRow: PropTypes.func,
  onViewRow: PropTypes.func,
};

export default function TicketTableRow({
  row,
  selected,
  onSelectRow,
  onViewRow,
}) {
  const theme = useTheme();

  const [openMenu, setOpenMenuActions] = useState(null);

  const handleOpenMenu = (event) => {
    setOpenMenuActions(event.currentTarget);
  };

  const handleCloseMenu = () => {
    setOpenMenuActions(null);
  };

  const { t } = useTranslation();
  const appCurrency = localStorage.getItem('app-currency') || 'CLP';

  return (
    <TableRow hover selected={selected}>
      {/* <TableCell padding="checkbox">
        <Checkbox checked={selected} onClick={onSelectRow} />
      </TableCell>
      <TableCell padding="checkbox" /> */}
      <TableCell align="left">{row?.ref_code}</TableCell>
      <TableCell align="center">{row?.vendor_name || "-"}</TableCell>
      <TableCell align="center">{row?.game_name}</TableCell>
      <TableCell align="center">{fDateTime(row?.created_on)}</TableCell>
      <TableCell align="center">{fCurrency(row?.mise)} {appCurrency}</TableCell>
      <TableCell align="center">{fCurrency(row?.gain)} {appCurrency}</TableCell>
      <TableCell align="center">
        <Label
          variant={theme.palette.mode === "light" ? "ghost" : "filled"}
          color={
            (row?.status === "WIN" && "success") ||
            (row?.status === "PENDING" && "warning") ||
            (row?.status === "WRONG" && "error") ||
            "default"
          }
          sx={{ textTransform: "uppercase", mb: 1 }}
        >
          {row?.status}
        </Label>
      </TableCell>

      {/* <TableCell align="right">
        <TableMoreMenu
          open={openMenu}
          onOpen={handleOpenMenu}
          onClose={handleCloseMenu}
          actions={
            <>
              <MenuItem
                onClick={() => {
                  onViewRow();
                  handleCloseMenu();
                }}
                disabled
              >
                <Iconify icon={"eva:eye-fill"} />
                {t("field.view")}
              </MenuItem>
            </>
          }
        />
      </TableCell> */}
    </TableRow>
  );
}
